contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address recipient, uint256 amount) public {
        vm.assume(recipient != address(0));
        vm.assume(recipient != address(c));
        vm.deal(address(c), amount);
        uint256 balanceBefore = recipient.balance;
        vm.prank(address(this));
        c.withdrawAll(recipient);
        uint256 balanceAfter = recipient.balance;
        assertTrue(balanceAfter == balanceBefore + amount);
    }
}

contract InvMutTest {
    C c;
    address owner;
    bool ownerCanWithdraw;
    bool nonOwnerCanWithdraw;

    constructor(C _c) {
        c = _c;
    }

    function test(address _recipient, address _nonOwner) public payable {
        owner = c.owner();
        require(address(this).balance >= 1 ether);
        require(msg.sender == owner);
        require(_nonOwner != owner);

        c.withdrawAll{value: 1 ether}(_recipient);

        (bool successOwner, ) = address(c).call(abi.encodeWithSignature("withdrawAll(address)", _recipient));
        ownerCanWithdraw = successOwner;

        (bool successNonOwner, ) = address(c).call(abi.encodeWithSignature("withdrawAll(address)", _recipient));
        nonOwnerCanWithdraw = successNonOwner;

        assert(ownerCanWithdraw && !nonOwnerCanWithdraw);
    }
}

